begin;
create temporary table social_test(k text primary key,id uuid default gen_random_uuid());
insert into social_test(k) values('author'),('viewer'),('outsider'),('operator'),('post'),('publicOther'),('draft'),('reel'),('comment'),('chat'),('share');
grant select,update on social_test to authenticated;
insert into auth.users(id,aud,role,email,email_confirmed_at) select id,'authenticated','authenticated','pulse-social-'||id::text||'@example.invalid',now() from social_test where k in ('author','viewer','outsider','operator');
insert into storage.objects(bucket_id,name,metadata) select 'pulse-social',a.id::text||'/'||r.id::text||'/video.mp4','{"mimetype":"video/mp4","size":100}'::jsonb from social_test a,social_test r where a.k='author' and r.k='reel';
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='author'),'role','authenticated')::text,true);
set local role authenticated;
select public.pulse_social_write((select id from social_test where k='post'),'post','Hello Pulse','[]','public',false);
select public.pulse_social_write((select id from social_test where k='post'),'post','Retry must not edit','[]','public',false);
select public.pulse_social_write((select id from social_test where k='draft'),'post','Private draft','[]','public',true);
select public.pulse_social_write((select id from social_test where k='reel'),'reel','#firstreel',jsonb_build_array(jsonb_build_object('kind','video','path',(select a.id::text||'/'||r.id::text||'/video.mp4' from social_test a,social_test r where a.k='author' and r.k='reel'),'mime','video/mp4')),'public',false);
update social_test set id=public.pulse_start_chat(array[(select id from social_test where k='viewer')],'Social share fixture',false) where k='chat';
do $$ begin
 if public.pulse_social_post((select id from social_test where k='post'))->>'body'<>'Hello Pulse' then raise exception 'FAIL: publishing retry changed content'; end if;
 if jsonb_array_length(public.pulse_social_feed('drafts',null,'all',null,null,20))<>1 then raise exception 'FAIL: own drafts'; end if;
 begin perform public.pulse_social_write(gen_random_uuid(),'reel','fake','[]','public',false); raise exception 'FAIL: empty reel'; exception when others then if sqlerrm='FAIL: empty reel' then raise; end if; end;
 begin update public.pulse_social_content set author_id=(select id from social_test where k='viewer') where id=(select id from social_test where k='post'); raise exception 'FAIL: direct writes allowed'; exception when insufficient_privilege then null; end;
end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='viewer'),'role','authenticated')::text,true);
set local role authenticated;
do $$ declare page jsonb; nextpage jsonb; begin
 if public.pulse_social_post((select id from social_test where k='draft')) is not null then raise exception 'FAIL: draft exposed'; end if;
 if exists(select 1 from public.pulse_social_content where id=(select id from social_test where k='draft')) then raise exception 'FAIL: draft RLS'; end if;
 page=public.pulse_social_feed('discovery',null,'all',null,null,1);
 nextpage=public.pulse_social_feed('discovery',null,'all',(page->0->>'created_at')::timestamptz,(page->0->>'id')::uuid,20);
 if jsonb_array_length(nextpage)<1 or nextpage->0->>'id'=page->0->>'id' then raise exception 'FAIL: pagination repeats or skips'; end if;
 begin perform public.pulse_social_edit((select id from social_test where k='post'),'forged',false); raise exception 'FAIL: foreign edit'; exception when others then if sqlerrm='FAIL: foreign edit' then raise; end if; end;
 begin perform public.pulse_social_write((select id from social_test where k='post'),'post','forged','[]','public',false); raise exception 'FAIL: foreign publish'; exception when others then if sqlerrm='FAIL: foreign publish' then raise; end if; end;
 begin perform public.pulse_social_review((select id from social_test where k='post')); raise exception 'FAIL: nonadmin review'; exception when others then if sqlerrm='FAIL: nonadmin review' then raise; end if; end;
 begin perform public.pulse_social_moderate((select id from social_test where k='post'),true); raise exception 'FAIL: nonadmin moderation'; exception when others then if sqlerrm='FAIL: nonadmin moderation' then raise; end if; end;
 begin update public.pulse_social_accounts set verified=true; raise exception 'FAIL: verified self grant'; exception when insufficient_privilege then null; end;
end $$;
select public.pulse_social_write((select id from social_test where k='publicOther'),'post','A public viewer post','[]','public',false);
select public.pulse_social_follow((select id from social_test where k='author'),true);
select public.pulse_social_action((select id from social_test where k='post'),'like',true);
select public.pulse_social_action((select id from social_test where k='post'),'like',true);
select public.pulse_social_action((select id from social_test where k='post'),'save',true);
select public.pulse_social_action((select id from social_test where k='post'),'repost',true);
select public.pulse_social_action((select id from social_test where k='reel'),'view',true);
select public.pulse_social_action((select id from social_test where k='reel'),'view',true);
select public.pulse_social_comment((select id from social_test where k='comment'),(select id from social_test where k='post'),'Nice post',false);
select public.pulse_social_share((select id from social_test where k='post'),(select id from social_test where k='chat'),(select id from social_test where k='share'));
select public.pulse_social_report((select id from social_test where k='post'),'Test fixture');
select public.pulse_social_report((select id from social_test where k='reel'),'Video fixture');
do $$ begin
 if (select body from public.pulse_messages where id=(select id from social_test where k='share')) like '%Hello Pulse%' then raise exception 'FAIL: share leaked caption'; end if;
 if (public.pulse_social_post((select id from social_test where k='post'))->>'likes')::int<>1 then raise exception 'FAIL: duplicate likes'; end if;
 if (public.pulse_social_post((select id from social_test where k='reel'))->>'views')::int<>1 then raise exception 'FAIL: duplicate views'; end if;
 if not (public.pulse_social_post((select id from social_test where k='post'))->>'saved')::boolean then raise exception 'FAIL: save'; end if;
 if not pulse_private.social_media_read((select a.id::text||'/'||r.id::text||'/video.mp4' from social_test a,social_test r where a.k='author' and r.k='reel')) then raise exception 'FAIL: published media'; end if;
end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='author'),'role','authenticated')::text,true);
set local role authenticated;
select public.pulse_social_action((select id from social_test where k='publicOther'),'repost',true);
select public.pulse_social_account(true,null);
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='outsider'),'role','authenticated')::text,true);
set local role authenticated;
do $$ begin
 if public.pulse_social_post((select id from social_test where k='post')) is not null then raise exception 'FAIL: private content exposed'; end if;
 if jsonb_array_length(public.pulse_social_feed('profile',(select id from social_test where k='author'),'all',null,null,20))<>0 then raise exception 'FAIL: private profile repost leaked'; end if;
 if exists(select 1 from public.pulse_social_reposts where user_id=(select id from social_test where k='author')) then raise exception 'FAIL: private repost identity leaked'; end if;
 if pulse_private.social_media_read((select a.id::text||'/'||r.id::text||'/video.mp4' from social_test a,social_test r where a.k='author' and r.k='reel')) then raise exception 'FAIL: private media'; end if;
 if exists(select 1 from public.pulse_social_saves where user_id=(select id from social_test where k='viewer')) then raise exception 'FAIL: saves leaked'; end if;
 if public.pulse_social_profile((select id from social_test where k='author'))->'analytics'<>'null'::jsonb then raise exception 'FAIL: private analytics'; end if;
 if public.pulse_social_follow((select id from social_test where k='author'),true)<>'pending' then raise exception 'FAIL: private follow accepted automatically'; end if;
 if public.pulse_social_post((select id from social_test where k='post')) is not null then raise exception 'FAIL: pending follower read'; end if;
 begin perform public.pulse_social_comment(gen_random_uuid(),(select id from social_test where k='post'),'forged',false); raise exception 'FAIL: private comment'; exception when others then if sqlerrm='FAIL: private comment' then raise; end if; end;
end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='author'),'role','authenticated')::text,true);
set local role authenticated;
select public.pulse_social_approve((select id from social_test where k='outsider'),true);
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='outsider'),'role','authenticated')::text,true);
set local role authenticated;
do $$ begin
 if public.pulse_social_post((select id from social_test where k='post')) is null then raise exception 'FAIL: approved follower missing'; end if;
end $$;
reset role;
insert into public.pulse_blocks(user_id,blocked_id) select a.id,b.id from social_test a,social_test b where a.k='author' and b.k='outsider';
set local role authenticated;
do $$ begin
 if public.pulse_social_post((select id from social_test where k='post')) is not null then raise exception 'FAIL: block visibility'; end if;
 if pulse_private.social_media_read((select a.id::text||'/'||r.id::text||'/video.mp4' from social_test a,social_test r where a.k='author' and r.k='reel')) then raise exception 'FAIL: blocked media'; end if;
end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='author'),'role','authenticated')::text,true);
set local role authenticated;
reset role;
insert into pulse_private.admins(user_id) select id from social_test where k='operator';
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='operator'),'role','authenticated')::text,true);
set local role authenticated;
do $$ begin
 if public.pulse_social_review((select id from social_test where k='post'))->>'body'<>'Hello Pulse' then raise exception 'FAIL: operator review'; end if;
 if not pulse_private.social_media_read((select a.id::text||'/'||r.id::text||'/video.mp4' from social_test a,social_test r where a.k='author' and r.k='reel')) then raise exception 'FAIL: operator media review'; end if;
end $$;
select public.pulse_social_moderate((select id from social_test where k='post'),true);
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='viewer'),'role','authenticated')::text,true);
set local role authenticated;
do $$ begin
 if public.pulse_social_post((select id from social_test where k='post')) is not null then raise exception 'FAIL: hidden post visible'; end if;
end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='operator'),'role','authenticated')::text,true);
set local role authenticated;
select public.pulse_social_moderate((select id from social_test where k='post'),false);
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='author'),'role','authenticated')::text,true);
set local role authenticated;
select public.pulse_social_comment((select id from social_test where k='comment'),null,'',true);
select public.pulse_social_edit((select id from social_test where k='reel'),'',true);
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from social_test where k='viewer'),'role','authenticated')::text,true);
set local role authenticated;
do $$ begin
 if public.pulse_social_post((select id from social_test where k='reel')) is not null then raise exception 'FAIL: deleted content visible'; end if;
 if pulse_private.social_media_read((select a.id::text||'/'||r.id::text||'/video.mp4' from social_test a,social_test r where a.k='author' and r.k='reel')) then raise exception 'FAIL: deleted media'; end if;
 if jsonb_array_length(public.pulse_social_comments((select id from social_test where k='post'),null,null))<>0 then raise exception 'FAIL: deleted comment visible'; end if;
end $$;
reset role;
do $$ begin
 if has_function_privilege('anon','public.pulse_social_write(uuid,text,text,jsonb,text,boolean)','execute') then raise exception 'FAIL: anonymous publishing'; end if;
 if has_function_privilege('authenticated','pulse_private.social_rate(text,int,int)','execute') then raise exception 'FAIL: internal rate accessible'; end if;
 if has_table_privilege('anon','public.pulse_social_content','select') then raise exception 'FAIL: anon table grant'; end if;
end $$;
select 'PASS: social post/reel CRUD, ownership, drafts, keyset pagination, engagement retries, private follow approval, blocking, storage, reporting/moderation, sharing, comments, analytics and grants' as result;
rollback;
